#include "DHT.h"

#define DHTPIN 12
#define DHTTYPE DHT11

DHT dht(DHTPIN, DHTTYPE);

int licznik = 0;
int liczba = 0;

int minimum, maksimum;
int jasnosc, wilgotnosc, temperatura;

char tryb = 'L';

bool poprzedniStanPrzycisku = LOW;

// Obsługa wyświetlacza
void Znak(int iNumer) {

  digitalWrite(8, ((iNumer == 0) ||
                   (iNumer == 1) ||
                   (iNumer == 7)) ? HIGH : LOW);

  switch (iNumer) {
    case 0: PORTD = 0b00000000; break;
    case 1: PORTD = 0b11100100; break;
    case 2: PORTD = 0b10010010; break;
    case 3: PORTD = 0b11000010; break;
    case 4: PORTD = 0b01100100; break;
    case 5: PORTD = 0b01001001; break;
    case 6: PORTD = 0b00001001; break;
    case 7: PORTD = 0b11100000; break;
    case 8: PORTD = 0b00000000; break;
    case 9: PORTD = 0b01000000; break;
    default: PORTD = 0b11011000; break;
  }
}

void setup() {

  dht.begin();

  for (int i = 2; i < 9; i++) {
    pinMode(i, OUTPUT);
  }

  pinMode(9, INPUT);
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  delay(1000);

  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {

  digitalWrite(11, LOW);

  delay(2);

  // Odczyt sensorów
  if (licznik++ > 100) {

    int odczyt = analogRead(A0);

    if (minimum > odczyt)
      minimum = odczyt;

    if (maksimum < odczyt)
      maksimum = odczyt;

    jasnosc = 0;

    if (minimum != maksimum) {
      jasnosc = 99 * (odczyt - minimum) /
                (maksimum - minimum);
    }

    float h = dht.readHumidity();
    float t = dht.readTemperature();

    if (!isnan(h))
      wilgotnosc = (int)h;

    if (!isnan(t))
      temperatura = (int)t;

    // Wybór wyświetlanej wartości
    switch (tryb) {

      case 'L':
        liczba = jasnosc;
        break;

      case 'H':
        liczba = wilgotnosc;
        break;

      case 'T':
        liczba = temperatura;
        break;
    }

    licznik = 0;

    // Wyświetlenie aktualnej wartości
    Znak(liczba);
  }

  // Obsługa przycisku
  bool stanPrzycisku = digitalRead(9);

  if (stanPrzycisku == HIGH &&
      poprzedniStanPrzycisku == LOW) {

    digitalWrite(10, LOW);
    digitalWrite(11, HIGH);

    // Zmiana trybu
    if (tryb == 'L') {
      tryb = 'H';
    }
    else if (tryb == 'H') {
      tryb = 'T';
    }
    else if (tryb == 'T') {
      tryb = 'L';
    }

    // Natychmiastowe wyświetlenie nowego trybu
    if (tryb == 'L')
      liczba = jasnosc;

    else if (tryb == 'H')
      liczba = wilgotnosc;

    else if (tryb == 'T')
      liczba = temperatura;

    Znak(liczba);

    delay(50); // eliminacja drgań styków
  }

  poprzedniStanPrzycisku = stanPrzycisku;
}
